PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE movie (
        available_globally boolean,
        release_date date,
        created_date timestamp not null,
        id integer,
        modified_date timestamp not null,
        runtime bigint,
        locale varchar(10),
        original_title varchar(255),
        title varchar(255) not null,
        primary key (id)
    );
CREATE TABLE tv_show (
        available_globally boolean,
        release_date date,
        created_date timestamp not null,
        id integer,
        modified_date timestamp not null,
        locale varchar(10),
        original_title varchar(255),
        title varchar(255) not null,
        primary key (id)
    );
CREATE TABLE season (
        release_date date,
        season_number integer,
        created_date timestamp not null,
        id integer,
        modified_date timestamp not null,
        runtime bigint,
        tv_show_id bigint,
        original_title varchar(255),
        title varchar(255) not null,
        primary key (id),
        foreign key (tv_show_id) references tv_show (id)
    );
CREATE TABLE view_summary (
        cumulative_weeks_in_top10 integer,
        end_date date not null,
        hours_viewed integer not null,
        start_date date not null,
        view_rank integer,
        views integer,
        created_date timestamp not null,
        id integer,
        modified_date timestamp not null,
        movie_id bigint,
        season_id bigint,
        duration varchar(20) not null check (duration in ('WEEKLY','SEMI_ANNUALLY')),
        primary key (id),
        foreign key (movie_id) references movie (id),
        foreign key (season_id) references season (id)
    );
CREATE INDEX idx_movie_title_runtime 
       on movie (title, runtime);
CREATE INDEX idx_season_title_runtime 
       on season (title, runtime);
CREATE INDEX fk_season_tv_show_id 
       on season (tv_show_id);
COMMIT;
